import java.util.*;

public class Main {
    static final long MOD = 998244353L;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int H = fs.nextInt();
        int W = fs.nextInt();
        char[][] a = new char[H][];
        for (int i = 0; i < H; i++) a[i] = fs.next().toCharArray();

        // If H > W, transpose to keep 2^H manageable.
        if (H > W) {
            char[][] b = new char[W][H];
            for (int i = 0; i < H; i++) {
                for (int j = 0; j < W; j++) {
                    b[j][i] = a[i][j];
                }
            }
            a = b;
            int tmp = H;
            H = W;
            W = tmp;
        }

        int N = 1 << H;
        long[] pow2 = new long[W + 1];
        pow2[0] = 1;
        for (int i = 1; i <= W; i++) pow2[i] = (pow2[i - 1] * 2) % MOD;

        // For each column, encode its pattern as H-bit mask:
        // bit i = 1 if black ('#'), 0 if white ('.')
        int[] cnt = new int[N];
        for (int j = 0; j < W; j++) {
            int mask = 0;
            for (int i = 0; i < H; i++) {
                if (a[i][j] == '#') mask |= 1 << i;
            }
            cnt[mask]++;
        }

        // f[S] = number of columns whose mask is subset of S
        long[] f = new long[N];
        for (int m = 0; m < N; m++) f[m] = cnt[m];
        for (int bit = 0; bit < H; bit++) {
            for (int m = 0; m < N; m++) {
                if ((m & (1 << bit)) != 0) {
                    f[m] += f[m ^ (1 << bit)];
                }
            }
        }

        // We count reachable final grids by considering the set R of rows whose last operation is a row operation.
        // For rows in R, final colors can be chosen arbitrarily: 2^|R|.
        // For rows not in R, each column's final color on those rows must be either
        // original column pattern restricted there, or its complement (depending on last column paint color).
        // Number of distinct resulting column-pattern choices over remaining rows:
        // count distinct pairs {x, ~x}; if x == ~x impossible for non-empty, so each pair contributes once.
        //
        // For fixed R, let T = complement rows (size t). A column mask m projects to p on T.
        // Two projected patterns p and q are equivalent if q = complement on T of p.
        // The number of distinct equivalence classes present among columns is:
        // g[R] = number of orbits under x <-> x^ALLT that appear.
        //
        // Then number of possible assignments of final column types = 2^{g[R]}.
        // Total for this R = 2^{|R|} * 2^{g[R]}.
        //
        // We can compute g[R]:
        // Let S = bitmask of rows in T (rows not in R), with size t.
        // A projected pattern x appears iff there exists original column mask m with (m & S) = x,
        // i.e. some subset on outside bits. Count of such columns is:
        // appear[x] iff sum_{u subset of (~S)} cnt[x | u] > 0.
        //
        // Using subset sums:
        // For a full H-bit mask y, number of columns with (columnMask & S) subset relation can be queried from f.
        // For a specific projected x on S, columns matching x on S are:
        // sum_{u subset of (~S)} cnt[x | u]
        // = number of columns z such that (z & S) = x.
        //
        // We compute g[R] by iterating projected x canonically with highest bit in S maybe 0 to avoid double count.
        // Since H <= about 20 after transpose, O(3^H) is fine.

        long ans = 0;
        int full = N - 1;

        for (int R = 0; R < N; R++) {
            int S = full ^ R; // rows controlled by columns in the end
            int t = Integer.bitCount(S);

            int g = 0;
            if (t == 0) {
                g = 0;
            } else {
                int lowbit = S & -S; // choose representative by forcing this bit 0
                // Enumerate x subset of S with (x & lowbit) == 0, one per pair {x, x^S}
                for (int x = S; ; x = (x - 1) & S) {
                    if ((x & lowbit) == 0) {
                        if (existsPattern(x, S, full, f) || existsPattern(x ^ S, S, full, f)) {
                            g++;
                        }
                    }
                    if (x == 0) break;
                }
            }

            long ways = pow2[Integer.bitCount(R)];
            ways = ways * pow2[g] % MOD;
            ans += ways;
            if (ans >= MOD) ans -= MOD;
        }

        System.out.println(ans % MOD);
    }

    // Checks whether there exists a column mask m such that (m & S) == x.
    // Let free = full ^ S. Need sum_{u subset free} cnt[x | u] > 0.
    // This equals number of masks in the subcube x..(x|free).
    // Using subset-sum f:
    // sum_{u subset free} cnt[x|u]
    // = sum_{y subset free} (-1)^{|y|} f[(x|free) ^ y]
    // by Möbius on free bits.
    static boolean existsPattern(int x, int S, int full, long[] f) {
        int free = full ^ S;
        int top = x | free;
        long sum = 0;
        for (int y = free; ; y = (y - 1) & free) {
            int bits = Integer.bitCount(y);
            if ((bits & 1) == 0) sum += f[top ^ y];
            else sum -= f[top ^ y];
            if (y == 0) break;
        }
        return sum > 0;
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}

